/* From Uiverse.io by KillerRP - Tags: 3d, clock, animated */
.__UIV_SCOPE__ .one-div {
  --box-width: 100px;
  width: var(--box-width);
  height: var(--box-width);
  border: 2px solid red;
  background-color: white;
  border-radius: 100%;
  position: relative;
  transform: scale(1);
  transition: 2s ease;
  cursor: pointer;
  box-shadow: 2px 2px 10px white;
}

.__UIV_SCOPE__ .one-div:hover {
  transform: scale(1.5);
  box-shadow: 2px 2px 50px yellow;
}

.__UIV_SCOPE__ .one-div::before, .__UIV_SCOPE__ .one-div::after {
  content: "";
  width: 2px;
  display: block;
  height: 100%;
  background: linear-gradient(black 50%, transparent 50%);
  border-radius: 20px;
  position: absolute;
  left: 50%;
  transform-origin: translate(-100%, -100%);
}

.__UIV_SCOPE__ .one-div::after {
  height: 100%;
  animation: secondsMotion 120s  infinite linear;
}

.__UIV_SCOPE__ .one-div::before {
  animation: secondsMotion 6s infinite linear;
}

@keyframes secondsMotion {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(360deg);
  }
}
